details.command:
kubectl patch networkpolicy default-deny-ingress -n policy --type merge --patch '
{
  "spec": {
    "ingress": [
      {
        "from": [
          {
            "podSelector": {
              "matchLabels": {
                "role": "allowed"
              }
            }
          }
        ],
        "ports": [
          {
            "protocol": "TCP",
            "port": 80
          }
        ]
      }
    ]
  }
}'
